h, w = map(int, input().split())
g = [[0] * w for _ in range(h)]
n = int(input())
for _ in range(n):
    l, d, r, c = map(int, input().split())
    for k in range(l):
        if d == 0:
            g[r - 1][c - 1 + k] = 1
        else:
            g[r - 1 + k][c - 1] = 1
for row in g:
    print(*row)
